#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <errno.h>
#include <assert.h>

#define MAX_SIZE 1024

int main(int argc, char *argv[])
{
	int fd;
	void *addr;
	int rc;
	int i;
	int count;
	char buf[MAX_SIZE];

	if (argc!= 2) {
		fprintf(stderr, "Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	addr = mmap(NULL, MAX_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
	if (addr == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	count = 0;
	for (i = 0; i < MAX_SIZE; i++) {
		if (addr[i] == '\n') {
			buf[count] = '\0';
			printf("%s\n", buf);
			count = 0;
		} else {
			buf[count] = addr[i];
			count++;
		}
	}

	rc = munmap(addr, MAX_SIZE);
	if (rc < 0) {
		perror("munmap");
		exit(1);
	}

	rc = close(fd);
	if (rc < 0) {
		perror("close");
		exit(1);
	}

	return 0;
}
