{
	char *buf;
	int fd;
	int len;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		printf("Error opening file\n");
		exit(1);
	}

	len = lseek(fd, 0, SEEK_END);
	lseek(fd, 0, SEEK_SET);

	buf = malloc(len);
	if (!buf) {
		printf("Error allocating memory\n");
		exit(1);
	}

	if (read(fd, buf, len)!= len) {
		printf("Error reading file\n");
		exit(1);
	}

	close(fd);

	if (strstr(buf, "nfsd4_setclientid_confirm")) {
		printf("1\n");
	} else {
		printf("0\n");
	}

	free(buf);

	return 0;
}
