int main(int argc, char *argv[])
{
	int fd;
	char *buf;
	int size;
	int i;
	int ret;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		return -1;
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		printf("open %s failed: %s\n", argv[1], strerror(errno));
		return -1;
	}

	size = lseek(fd, 0, SEEK_END);
	if (size < 0) {
		printf("lseek failed: %s\n", strerror(errno));
		close(fd);
		return -1;
	}

	buf = mmap(NULL, size, PROT_READ, MAP_PRIVATE, fd, 0);
	if (buf == MAP_FAILED) {
		printf("mmap failed: %s\n", strerror(errno));
		close(fd);
		return -1;
	}

	close(fd);

	for (i = 0; i < size; i++) {
		ret = __ext4_check_dir_entry("test", 0, NULL, NULL, (struct ext4_dir_entry_2 *)buf, NULL, i);
		if (ret)
			break;
	}

	if (ret)
		printf("1\n");
	else
		printf("0\n");

	munmap(buf, size);

	return 0;
}
