#define PAGE_SIZE 4096

int main(int argc, char *argv[])
{
	int fd;
	char *addr;
	char *buf;
	int i;

	if (argc!= 2) {
		fprintf(stderr, "Usage: %s <file>\n", argv[0]);
		exit(EXIT_FAILURE);
	}

	fd = open(argv[1], O_RDWR | O_CREAT, 0644);
	if (fd == -1) {
		perror("open");
		exit(EXIT_FAILURE);
	}

	if (ftruncate(fd, PAGE_SIZE) == -1) {
		perror("ftruncate");
		exit(EXIT_FAILURE);
	}

	addr = mmap(NULL, PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	if (addr == MAP_FAILED) {
		perror("mmap");
		exit(EXIT_FAILURE);
	}

	buf = malloc(PAGE_SIZE);
	if (buf == NULL) {
		perror("malloc");
		exit(EXIT_FAILURE);
	}

	for (i = 0; i < PAGE_SIZE; i++)
		buf[i] = 'a';

	memcpy(addr, buf, PAGE_SIZE);

	munmap(addr, PAGE_SIZE);
	close(fd);
	free(buf);

	exit(EXIT_SUCCESS);
}
