#define PAGE_SIZE 4096

int main(int argc, char **argv)
{
	int fd;
	void *addr;
	size_t len;
	int ret;

	fd = open("extent_tree.c", O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	len = lseek(fd, 0, SEEK_END);
	if (len < 0) {
		perror("lseek");
		exit(1);
	}

	addr = mmap(NULL, len, PROT_READ, MAP_PRIVATE, fd, 0);
	if (addr == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	ret = memmem(addr, len, "ext_tree_encode_commit", 25);
	if (ret) {
		printf("1\n");
	} else {
		printf("0\n");
	}

	munmap(addr, len);
	close(fd);

	return 0;
}
