#include <stdlib.h>

int main(int argc, char *argv[])
{
	int value = atoi(argv[1]);
	int n = atoi(argv[2]);
	int a;

	if (!value ||!n)
		return 0;

	a = value >> (n - 1);
	if (a && a!= -1)
		return value < 0? 1 << (n - 1) : (1 << (n - 1)) - 1;
	return value & ((1 << n) - 1);
}
