#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <errno.h>

#define PAGE_SIZE 4096

int main(int argc, char **argv)
{
	int fd;
	struct stat sb;
	void *addr;
	char *p;
	int i;

	if (argc!= 2) {
		fprintf(stderr, "Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd == -1) {
		perror("open");
		exit(1);
	}

	if (fstat(fd, &sb) == -1) {
		perror("fstat");
		exit(1);
	}

	addr = mmap(NULL, sb.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
	if (addr == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	p = addr;
	for (i = 0; i < sb.st_size; i++) {
		if (p[i] == 'e' && p[i+1] == 't' && p[i+2] =='s' && p[i+3] == '_') {
			printf("1\n");
			exit(0);
		}
	}

	printf("0\n");
	exit(0);
}
