	char *buf;
	ssize_t bytes_read;
	int i;
	int count = 0;
	int off = 0;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		exit(1);
	}

	fd = open(argv[1], O_RDONLY);
	if (fd < 0) {
		perror("open");
		exit(1);
	}

	buf = mmap(NULL, BUF_SIZE, PROT_READ, MAP_PRIVATE, fd, 0);
	if (buf == MAP_FAILED) {
		perror("mmap");
		exit(1);
	}

	bytes_read = read(fd, buf, BUF_SIZE);
	if (bytes_read < 0) {
		perror("read");
		exit(1);
	}

	for (i = 0; i < bytes_read; i++) {
		if (buf[i] == 'i' && buf[i+1] == 'o' && buf[i+2] == 'r' && buf[i+3] == 'e') {
			count++;
		}
	}

	printf("Count: %d\n", count);

	return 0;
}
