#define PAGE_SIZE 4096

int main(int argc, char **argv)
{
	int fd;
	char *buf;
	struct stat st;
	int i;
	int ret;

	if (argc!= 2) {
		printf("Usage: %s <file>\n", argv[0]);
		return -1;
	}

	fd = open(argv[1], O_RDWR);
	if (fd < 0) {
		perror("open");
		return -1;
	}

	ret = fstat(fd, &st);
	if (ret < 0) {
		perror("fstat");
		return -1;
	}

	buf = mmap(NULL, st.st_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
	if (buf == MAP_FAILED) {
		perror("mmap");
		return -1;
	}

	for (i = 0; i < st.st_size; i += PAGE_SIZE) {
		buf[i] = 0;
	}

	ret = msync(buf, st.st_size, MS_SYNC);
	if (ret < 0) {
		perror("msync");
		return -1;
	}

	ret = munmap(buf, st.st_size);
	if (ret < 0) {
		perror("munmap");
		return -1;
	}

	ret = close(fd);
	if (ret < 0) {
		perror("close");
		return -1;
	}

	return 0;
}
