	char *cwe_str;
	char *cwe_str_ptr;
	int cwe_num = 0;
	int i;

	if (argc!= 2) {
		printf("Usage: %s <string>\n", argv[0]);
		return 1;
	}

	cwe_str = strdup(argv[1]);
	if (!cwe_str) {
		printf("Failed to allocate memory\n");
		return 1;
	}

	cwe_str_ptr = cwe_str;
	while (cwe_num < CWE_MAX_NUM) {
		cwe_str_ptr = strstr(cwe_str_ptr, "CWE-");
		if (!cwe_str_ptr)
			break;

		cwe_str_ptr += 4;
		cwe_list[cwe_num] = strndup(cwe_str_ptr, CWE_MAX_LEN);
		if (!cwe_list[cwe_num]) {
			printf("Failed to allocate memory\n");
			return 1;
		}

		cwe_num++;
		cwe_str_ptr++;
	}

	printf("[");
	for (i = 0; i < cwe_num; i++) {
		if (i)
			printf(", ");
		printf("\"%s\"", cwe_list[i]);
	}
	printf("]\n");

	return 0;
}
